N = "8-1"


def titulo():
    return t("Multiple findings: judging conclusions with evidence", "Hallazgos múltiples: evaluar conclusiones con evidencia")


def anc(en, es):
    return en if C.L == "en" else es


def R(x):
    return f'<span class="raiz">{x}</span>'


def svg_divergencia():
    tr = {"1 · Método": "1 · Method", "2 · Muestra": "2 · Sample", "3 · Alcance": "3 · Scope",
          "¿Midieron de la misma": "Did they measure", "manera?": "the same way?", "Si no, no son comparables": "If not, they are not comparable",
          "¿Estudiaron lo mismo,": "Did they study the same thing,", "dónde y cuándo?": "in the same place and time?", "Si no, pueden ser ambos ciertos": "If not, both can be true",
          "¿Afirman lo mismo, con": "Do they claim the same thing,", "la misma amplitud?": "just as broadly?", "Si no, hablan de cosas distintas": "If not, they talk about different things",
          "Solo si los tres coinciden y los resultados siguen": "Only if all three match and the results still", "siendo incompatibles hay contradicción real": "cannot both be true is there a real contradiction",
          "Reconciliar no es decidir quién gana: es localizar dónde difieren": "Reconciling is not deciding who wins: it is finding where they differ"}
    return C.svg_orig("8-1_0", tr, "Diagram of the three checks to make before saying two studies contradict each other. First, method: if they measured in different ways, the results may not be comparable. Second, sample: if they studied different populations, places, or periods, both results can be true at once. Third, scope: if one makes a general claim and the other a specific one, they are not talking about the same thing. Only when method, sample, and scope all match and the results still cannot both be true is there a real contradiction that needs more research.")


